import UIKit

struct SnapshotBuilder {
    static func createSnapshot(items: [String]) -> NSDiffableDataSourceSnapshot<Int, String> {
        var snap = NSDiffableDataSourceSnapshot<Int, String>()
        snap.appendSections([1])
        snap.appendItems(items)
        return snap
    }
}

let builtSnap = SnapshotBuilder.createSnapshot(items: ["One", "Two", "Three"])
print("Built items count: \(builtSnap.numberOfItems)")

import UIKit

class LayoutFactory {
    @MainActor
    static func createListLayout(rowHeight: CGFloat) -> UICollectionViewCompositionalLayout {
        let itemSize = NSCollectionLayoutSize(widthDimension: .fractionalWidth(1.0), heightDimension: .fractionalHeight(1.0))
        let item = NSCollectionLayoutItem(layoutSize: itemSize)
        let groupSize = NSCollectionLayoutSize(widthDimension: .fractionalWidth(1.0), heightDimension: .absolute(rowHeight))
        let group = NSCollectionLayoutGroup.vertical(layoutSize: groupSize, subitems: [item])
        let section = NSCollectionLayoutSection(group: group)
        return UICollectionViewCompositionalLayout(section: section)
    }
}

let listLayout = LayoutFactory.createListLayout(rowHeight: 80)
print("Layout created: \(!listLayout.description.isEmpty)")

